∀ {V : Type u} (G : SimpleGraph.{u} V) {a b : V} {e : Sym2.{u} V},
  @Ne.{u + 1} V a b →
    @Membership.mem.{u, u} (Sym2.{u} V) (Set.{u} (Sym2.{u} V)) (@Set.instMembership.{u} (Sym2.{u} V))
        (@SimpleGraph.incidenceSet.{u} V G a) e →
      @Membership.mem.{u, u} (Sym2.{u} V) (Set.{u} (Sym2.{u} V)) (@Set.instMembership.{u} (Sym2.{u} V))
          (@SimpleGraph.incidenceSet.{u} V G b) e →
        @SimpleGraph.Adj.{u} V G a b

∀ {V : Type u} (G : SimpleGraph.{u} V) (v w : V),
  @LE.le.{u} (Set.{u} V) (@Set.instLE.{u} V) (@SimpleGraph.commonNeighbors.{u} V G v w)
    (@SimpleGraph.neighborSet.{u} V G v)

∀ {V : Type u} (G : SimpleGraph.{u} V) (v w : V),
