      @DecidablePred.{u + 1} (Sym2.{u} V) fun x =>
        @Membership.mem.{u, u} (Sym2.{u} V) (Set.{u} (Sym2.{u} V)) (@Set.instMembership.{u} (Sym2.{u} V))
          (@SimpleGraph.edgeSet.{u} V G) x

(V : Type u_2) →
  @OrderEmbedding.{u_2, u_2} (SimpleGraph.{u_2} V) (Set.{u_2} (Sym2.{u_2} V)) (@SimpleGraph.instLE.{u_2} V)
    (@Set.instLE.{u_2} (Sym2.{u_2} V))

∀ {V : Type u} (s : Set.{u} (Sym2.{u} V)),
  @Eq.{u + 1} (Set.{u} (Sym2.{u} V)) (@SimpleGraph.edgeSet.{u} V (@SimpleGraph.fromEdgeSet.{u} V s))
    (@SDiff.sdiff.{u} (Set.{u} (Sym2.{u} V)) (@Set.instSDiff.{u} (Sym2.{u} V)) s (@Sym2.diagSet.{u} V))

∀ {V : Type u} {G₁ G₂ : SimpleGraph.{u} V},
  @LE.le.{u} (SimpleGraph.{u} V) (@SimpleGraph.instLE.{u} V) G₁ G₂ →
    @LE.le.{u} (Set.{u} (Sym2.{u} V)) (@Set.instLE.{u} (Sym2.{u} V)) (@SimpleGraph.edgeSet.{u} V G₁)
      (@SimpleGraph.edgeSet.{u} V G₂)

∀ {V : Type u} {s : Set.{u} (SimpleGraph.{u} V)},
  @Set.Nonempty.{u} (SimpleGraph.{u} V) s →
    @Eq.{u + 1} (Set.{u} (Sym2.{u} V))
      (@SimpleGraph.edgeSet.{u} V (@InfSet.sInf.{u} (SimpleGraph.{u} V) (@SimpleGraph.infSet.{u} V) s))
      (@Set.sInter.{u} (Sym2.{u} V)
        (@Set.image.{u, u} (SimpleGraph.{u} V) (Set.{u} (Sym2.{u} V)) (@SimpleGraph.edgeSet.{u} V) s))

∀ {V : Type u} (G : SimpleGraph.{u} V),
  @LE.le.{u} (Set.{u} (Sym2.{u} V)) (@Set.instLE.{u} (Sym2.{u} V)) (@SimpleGraph.edgeSet.{u} V G)
    (@Compl.compl.{u} (Set.{u} (Sym2.{u} V)) (@Set.instCompl.{u} (Sym2.{u} V)) (@Sym2.diagSet.{u} V))

∀ {V : Type u} (G : SimpleGraph.{u} V) [inst : DecidableEq.{u + 1} V] {v : V} {e : Sym2.{u} V}
  (h :
    @Membership.mem.{u, u} (Sym2.{u} V) (Set.{u} (Sym2.{u} V)) (@Set.instMembership.{u} (Sym2.{u} V))
      (@SimpleGraph.incidenceSet.{u} V G v) e),
  @Membership.mem.{u, u} (Sym2.{u} V) (Set.{u} (Sym2.{u} V)) (@Set.instMembership.{u} (Sym2.{u} V))
    (@SimpleGraph.incidenceSet.{u} V G (@SimpleGraph.otherVertexOfIncident.{u} V G inst v e h)) e

∀ {V : Type u} (G : SimpleGraph.{u} V) {e : Sym2.{u} V},
  @Membership.mem.{u, u} (Sym2.{u} V) (Set.{u} (Sym2.{u} V)) (@Set.instMembership.{u} (Sym2.{u} V))
      (@SimpleGraph.edgeSet.{u} V G) e →
    ∀ {v : V}
      (h :
        @Membership.mem.{u, u} V (Sym2.{u} V) (@SetLike.instMembership.{u, u} (Sym2.{u} V) V (@Sym2.instSetLike.{u} V))
          e v),
      @Ne.{u + 1} V (@Sym2.Mem.other.{u} V v e h) v

∀ {V : Type u} {ι : Sort u_2} {f : ι → Set.{u} (Sym2.{u} V)},
  @Eq.{u + 1} (SimpleGraph.{u} V) (@SimpleGraph.fromEdgeSet.{u} V (⋂ i, f i))
    (⨅ i, @SimpleGraph.fromEdgeSet.{u} V (f i))

∀ {V : Type u} {ι : Sort u_2} {f : ι → Set.{u} (Sym2.{u} V)},
  @Eq.{u + 1} (SimpleGraph.{u} V) (@SimpleGraph.fromEdgeSet.{u} V (⋃ i, f i))
    (⨆ i, @SimpleGraph.fromEdgeSet.{u} V (f i))

∀ {V : Type u} {s t : Set.{u} (Sym2.{u} V)},
  @LE.le.{u} (Set.{u} (Sym2.{u} V)) (@Set.instLE.{u} (Sym2.{u} V)) s t →
    @LE.le.{u} (SimpleGraph.{u} V) (@SimpleGraph.instLE.{u} V) (@SimpleGraph.fromEdgeSet.{u} V s)
      (@SimpleGraph.fromEdgeSet.{u} V t)

∀ {V : Type u} (G : SimpleGraph.{u} V) (v : V),
  @LE.le.{u} (Set.{u} (Sym2.{u} V)) (@Set.instLE.{u} (Sym2.{u} V)) (@SimpleGraph.incidenceSet.{u} V G v)
    (@SimpleGraph.edgeSet.{u} V G)

∀ {V : Type u} (G : SimpleGraph.{u} V) [inst : DecidableEq.{u + 1} V] {v w : V}
  (h : @Membership.mem.{u, u} V (Set.{u} V) (@Set.instMembership.{u} V) (@SimpleGraph.neighborSet.{u} V G v) w),
  @Eq.{u + 1} V (@SimpleGraph.otherVertexOfIncident.{u} V G inst v (@Sym2.mk.{u} V v w) ⋯) w

∀ {V : Type u} (G : SimpleGraph.{u} V) [inst : DecidableEq.{u + 1} V] {v : V} {e : Sym2.{u} V}
  (h :
    @Membership.mem.{u, u} (Sym2.{u} V) (Set.{u} (Sym2.{u} V)) (@Set.instMembership.{u} (Sym2.{u} V))
      (@SimpleGraph.incidenceSet.{u} V G v) e),
  @Membership.mem.{u, u} V (Set.{u} V) (@Set.instMembership.{u} V) (@SimpleGraph.neighborSet.{u} V G v)
    (@SimpleGraph.otherVertexOfIncident.{u} V G inst v e h)

{V : Type u} →
  (s : Set.{u} (Sym2.{u} V)) →
    [@DecidablePred.{u + 1} (Sym2.{u} V) fun x =>
          @Membership.mem.{u, u} (Sym2.{u} V) (Set.{u} (Sym2.{u} V)) (@Set.instMembership.{u} (Sym2.{u} V)) s x] →
      [DecidableEq.{u + 1} V] →
        @DecidableRel.{u + 1, u + 1} V V (@SimpleGraph.Adj.{u} V (@SimpleGraph.fromEdgeSet.{u} V s))

{V : Type u} →
  (G : SimpleGraph.{u} V) →
    (v : V) →
      [@DecidableRel.{u + 1, u + 1} V V (@SimpleGraph.Adj.{u} V G)] →
        @DecidablePred.{u + 1} V fun x =>
          @Membership.mem.{u, u} V (Set.{u} V) (@Set.instMembership.{u} V) (@SimpleGraph.neighborSet.{u} V G v) x

∀ {V : Type u} {G G' : SimpleGraph.{u} V},
  @LE.le.{u} (SimpleGraph.{u} V) (@SimpleGraph.instLE.{u} V) G G' →
    ∀ (v : V),
      @LE.le.{u} (Set.{u} V) (@Set.instLE.{u} V) (@SimpleGraph.neighborSet.{u} V G v)
        (@SimpleGraph.neighborSet.{u} V G' v)

∀ {V : Type u} {a b : V} {s : Set.{u} (SimpleGraph.{u} V)},
  @Set.Nonempty.{u} (SimpleGraph.{u} V) s →
    Iff (@SimpleGraph.Adj.{u} V (@InfSet.sInf.{u} (SimpleGraph.{u} V) (@SimpleGraph.infSet.{u} V) s) a b)
      (∀ (G : SimpleGraph.{u} V),
        @Membership.mem.{u, u} (SimpleGraph.{u} V) (Set.{u} (SimpleGraph.{u} V))
            (@Set.instMembership.{u} (SimpleGraph.{u} V)) s G →
          @SimpleGraph.Adj.{u} V G a b)

∀ {V : Type u} {G G' : SimpleGraph.{u} V},
  @LE.le.{u} (SimpleGraph.{u} V) (@SimpleGraph.instLE.{u} V) G G' →
    @LE.le.{u} (Set.{u} V) (@Set.instLE.{u} V) (@SimpleGraph.support.{u} V G) (@SimpleGraph.support.{u} V G')

∀ {V : Type u} (G : SimpleGraph.{u} V) [Subsingleton.{u + 1} V],
